  "/./include/modules/base/items/song/sing": "<input type=\"hidden\" name=\"mode\" value=\"command\">\n<input type=\"hidden\" id=\"command\" name=\"command\" value=\"song\">\n<input type=\"hidden\" id=\"song_choice\" name=\"song_choice\" value='0'>\n请选择你要唱的歌：<br><br>\n<!--{eval $ls = \\song\\get_available_songlist();}-->\n<!--{if empty($ls)}-->\n<span class=\"yellow b\">好像你一首歌都不会唱的样子……</span><br>\n<!--{else}--> \n<!--{eval eval(import_module('song'));}-->\n<!--{loop $ls $i}-->\n<input type=\"button\" class=\"cmdbutton\" value=\"{$songlist[$i]['songname']}\" style=\"width: 180px;\" onclick=\"$('song_choice').value='{$i}';postCmd('gamecmd','command.php');this.disabled=true;\"><br>\n<!--{/loop}-->\n<!--{/if}-->\n<br>\n<input type=\"button\" class=\"cmdbutton\" id=\"x\" value=\"[X]返回\" onclick=\"$('command').value='menu'; postCmd('gamecmd','command.php');this.disabled=true;\">",
