  "/./include/modules/extra/card/skills/skill439/desc": "<!--{eval eval(import_module('skill439','itemmain'));}-->\n<!--{eval $___TEMP_SKILL_ID=439;}-->\n<!--{eval $ctype = \\skillbase\\skill_getvalue(439,'type',$who); }-->\n{template MOD_CLUBBASE_SKILLDESC_START}\n<span>\n面子\n</span>\n{template MOD_CLUBBASE_SKILLDESC_MID1}\n<td class=\"skilldesc_left b3\"><span class=\"skilldesc\">\n被同种武器第二次攻击时最终伤害<span class=\"yellow b\">-75%</span>，但不能被连续触发。<br>\n<!--{if $ctype!='X'}-->\n当前生效武器系别：<span class=\"cyan b\">{$iteminfo['W'.$ctype]}</span>\n<!--{else}-->\n<span class=\"red b\">当前未生效</span>\n<!--{/if}-->\n</span></td>\n<td class=\"skilldesc_right b3\">\n</td>\n{template MOD_CLUBBASE_SKILLDESC_MID2}\n<!--{if empty($___TEMP_THIS_SKILL_ACQUIRED)}-->\n<span class=\"yellow b\">\n</span>\n<!--{/if}-->\n{template MOD_CLUBBASE_SKILLDESC_END}\n",
