  "/./include/modules/extra/card/skills/skill440/desc": "<!--{eval eval(import_module('skill440','sys','bufficons'));}-->\n<!--{eval $___TEMP_SKILL_ID=440;}-->\n{template MOD_CLUBBASE_SKILLDESC_START}\n<span>\n父爱\n</span>\n{template MOD_CLUBBASE_SKILLDESC_MID1}\n<td class=\"skilldesc_left b3\"><span class=\"skilldesc\">\n<!--{eval $st = \\bufficons\\bufficons_check_buff_state(440,$who);$rm=$tmp_totsec-$tmp_nowsec;}-->\n<span class=\"yellow b\">战斗技</span>&nbsp;&nbsp;本次战斗中敌方玩家所有技能无效，并使敌人<span class=\"red b\">烧伤</span><span class=\"purple b\">中毒</span>，且<span class=\"yellow b\">40</span>秒内无法解除异常状态，技能冷却时间<span class=\"cyan b\">$skill440_cd</span>秒<br>\n<!--{if 2 == $st}-->\n<span class=\"cyan b\">技能冷却中，冷却时间还剩<span>$rm</span>秒。</span><br>\n<!--{elseif 3 == $st}-->\n<span class=\"yellow b\">技能已经就绪，可以发动<span>\n<!--{/if}-->\n</span></td>\n<td class=\"skilldesc_right b3\">\n</td>\n{template MOD_CLUBBASE_SKILLDESC_MID2}\n<!--{if empty($___TEMP_THIS_SKILL_ACQUIRED)}-->\n<span class=\"yellow b\">\n</span>\n<!--{/if}-->\n{template MOD_CLUBBASE_SKILLDESC_END}\n",
  "/./include/modules/extra/card/skills/skill441/desc": "<!--{eval eval(import_module('skill441'));}-->\n<!--{eval $___TEMP_SKILL_ID=441;}-->\n{template MOD_CLUBBASE_SKILLDESC_START}\n<span>\n嗑药\n</span>\n{template MOD_CLUBBASE_SKILLDESC_MID1}\n<td class=\"skilldesc_left b3\"><span class=\"skilldesc\">\n每有一处异常状态造成的物理伤害就提高<span class=\"yellow b\">35%</span>。<br>\n</span></td>\n<td class=\"skilldesc_right b3\">\n</td>\n{template MOD_CLUBBASE_SKILLDESC_MID2}\n<!--{if empty($___TEMP_THIS_SKILL_ACQUIRED)}-->\n<span class=\"yellow b\">\n</span>\n<!--{/if}-->\n{template MOD_CLUBBASE_SKILLDESC_END}\n",
