  "/./include/modules/extra/card/skills/skill443/desc": "<!--{eval $___TEMP_SKILL_ID=443;}-->\n{template MOD_CLUBBASE_SKILLDESC_START}\n<span>\n决斗\n</span>\n{template MOD_CLUBBASE_SKILLDESC_MID1}\n<!--{eval $gold_r = ($club==3?2.5:1.5);}-->\n<!--{eval $gold_p = round($lvl*$gold_r);}-->\n<td class=\"skilldesc_left b3\"><span class=\"skilldesc\">\n当你在战斗中击杀敌人时，你立即获得<span class=\"yellow b\">10</span>点基础攻击力。<br>\n</span></td>\n<td class=\"skilldesc_right b3\">\n</td>\n{template MOD_CLUBBASE_SKILLDESC_MID2}\n<!--{if empty($___TEMP_THIS_SKILL_ACQUIRED)}-->\n<span class=\"yellow b\">\n</span>\n<!--{/if}-->\n{template MOD_CLUBBASE_SKILLDESC_END}\n",
  "/./include/modules/extra/card/skills/skill444/desc": "<!--{eval eval(import_module('skill444'));}-->\n<!--{eval $___TEMP_SKILL_ID=444;}-->\n{template MOD_CLUBBASE_SKILLDESC_START}\n<span>\n怒吼\n</span>\n{template MOD_CLUBBASE_SKILLDESC_MID1}\n<td class=\"skilldesc_left b3\"><span class=\"skilldesc\">\n造成的战斗伤害<span class=\"yellow b\">×2</span>，命中率大幅降低。<br>\n</span></td>\n<td class=\"skilldesc_right b3\">\n</td>\n{template MOD_CLUBBASE_SKILLDESC_MID2}\n<!--{if empty($___TEMP_THIS_SKILL_ACQUIRED)}-->\n<span class=\"yellow b\">\n</span>\n<!--{/if}-->\n{template MOD_CLUBBASE_SKILLDESC_END}\n",
