  "/./include/modules/extra/club/skills/skill217/desc": "<!--{eval eval(import_module('skill217'));}-->\n<!--{eval $___TEMP_SKILL_ID=217;}-->\n{template MOD_CLUBBASE_SKILLDESC_START}\n<span>\n特攻\n</span>\n{template MOD_CLUBBASE_SKILLDESC_MID1}\n<td class=\"skilldesc_left b3\"><span class=\"skilldesc\">\n<!--{eval $clv = (int)\\skillbase\\skill_getvalue(217,'lvl'); }-->\n<!--{eval $totlv = count($upgradecost)-1; }-->\n<span class=\"lime b\">当前级别$clv/$totlv</span>&nbsp;\n<!--{if $upgradecost[$clv] !== -1}-->消耗<span class=\"lime b\">$upgradecost[$clv]</span>点技能点升至下一级<!--{/if}--><br>\n你造成的属性伤害提高<span class=\"yellow b\">$dmggain[$clv]%</span><br>\n</span></td>\n<td class=\"skilldesc_right b3\">\n<!--{if $upgradecost[$clv] !== -1}-->\n<!--{if $skillpoint>=$upgradecost[$clv]}-->\n<input type=\"button\" style=\"width:46px\" onclick=\"$('mode').value='special';$('command').value='skill217_special';$('subcmd').value='upgrade';postCmd('gamecmd','command.php');this.disabled=true;\" value=\"升级\">\n<!--{else}-->\n<input type=\"button\" style=\"width:46px\" disabled=\"true\" value=\"升级\">\n<!--{/if}-->\n<!--{/if}-->\n</td>\n{template MOD_CLUBBASE_SKILLDESC_MID2}\n<!--{if empty($___TEMP_THIS_SKILL_ACQUIRED)}-->\n<span class=\"yellow b\">\n</span>\n<!--{/if}-->\n{template MOD_CLUBBASE_SKILLDESC_END}\n",
  "/./include/modules/extra/club/skills/skill218/desc": "<!--{eval eval(import_module('skill218'));}-->\n<!--{eval $___TEMP_SKILL_ID=218;}-->\n{template MOD_CLUBBASE_SKILLDESC_START}\n<span>\n渗透\n</span>\n{template MOD_CLUBBASE_SKILLDESC_MID1}\n<td class=\"skilldesc_left b3\"><span class=\"skilldesc\">\n<!--{eval $clv = (int)\\skillbase\\skill_getvalue(218,'lvl'); }-->\n<!--{eval $totlv = count($upgradecost)-1; }-->\n<span class=\"lime b\">当前级别$clv/$totlv</span>&nbsp;\n<!--{if $upgradecost[$clv] !== -1}-->消耗<span class=\"lime b\">$upgradecost[$clv]</span>点技能点升至下一级<!--{/if}--><br>\n你造成异常状态的概率提高<span class=\"yellow b\">$infrgain[$clv]%</span><br>对已受伤或有异常状态的敌人造成的最终伤害提高<span class=\"yellow b\">$extdmg[$clv]%</span><br>\n</span></td>\n<td class=\"skilldesc_right b3\">\n<!--{if $upgradecost[$clv] !== -1}-->\n<!--{if $skillpoint>=$upgradecost[$clv]}-->\n<input type=\"button\" style=\"width:46px\" onclick=\"$('mode').value='special';$('command').value='skill218_special';$('subcmd').value='upgrade';postCmd('gamecmd','command.php');this.disabled=true;\" value=\"升级\">\n<!--{else}-->\n<input type=\"button\" style=\"width:46px\" disabled=\"true\" value=\"升级\">\n<!--{/if}-->\n<!--{/if}-->\n</td>\n{template MOD_CLUBBASE_SKILLDESC_MID2}\n<!--{if empty($___TEMP_THIS_SKILL_ACQUIRED)}-->\n<span class=\"yellow b\">\n</span>\n<!--{/if}-->\n{template MOD_CLUBBASE_SKILLDESC_END}\n",
