  "/./include/modules/extra/club/skills/skill60/desc": "<!--{eval eval(import_module('skill60'));}-->\n<!--{eval $___TEMP_SKILL_ID=60;}-->\n<!--{eval $ragecost = \\skill60\\get_rage_cost60();}-->\n{template MOD_CLUBBASE_SKILLDESC_START}\n<span>\n恐惧\n</span>\n{template MOD_CLUBBASE_SKILLDESC_MID1}\n<td class=\"skilldesc_left b3\"><span class=\"skilldesc\">\n<span class=\"yellow b\">战斗技</span>：本次攻击物理伤害<span class=\"yellow b\">+x%</span>，<span class=\"yellow b\">x</span>为敌方已损失生命值百分比<br>\n<!--{if $club==24}-->\n发动消耗<span class=\"yellow b\">(50-等级)</span>点怒气，最低20点<!--{if !empty($___TEMP_THIS_SKILL_ACQUIRED)}-->(目前为<span class=\"yellow b\">$ragecost</span>点)<!--{/if}--><br>\n<!--{else}-->\n发动消耗<span class=\"yellow b\">(50-0.7*等级)</span>点怒气，最低25点<!--{if !empty($___TEMP_THIS_SKILL_ACQUIRED)}-->(目前为<span class=\"yellow b\">$ragecost</span>点)<!--{/if}--><br>\n<!--{/if}-->\n</span></td>\n<td class=\"skilldesc_right b3\">\n</td>\n{template MOD_CLUBBASE_SKILLDESC_MID2}\n<!--{if empty($___TEMP_THIS_SKILL_ACQUIRED)}-->\n<span class=\"yellow b\">\n12级时解锁\n</span>\n<!--{/if}-->\n{template MOD_CLUBBASE_SKILLDESC_END}\n",
  "/./include/modules/extra/club/skills/skill61/desc": "<!--{eval eval(import_module('skill61'));}-->\n<!--{eval $___TEMP_SKILL_ID=61;}-->\n<!--{eval $skprocrate = \\skill61\\get_sk_procrate61();}-->\n<!--{eval $hpprocrate = \\skill61\\get_hp_procrate61();}-->\n{template MOD_CLUBBASE_SKILLDESC_START}\n<span>\n黑暗\n</span>\n{template MOD_CLUBBASE_SKILLDESC_MID1}\n<td class=\"skilldesc_left b3\"><span class=\"skilldesc\">\n当你攻击敌人时，你有<span class=\"yellow b\">$skprocrate%</span>几率吸取敌人<span class=\"yellow b\">1</span>点全系熟练，<br>\n<span class=\"yellow b\">$hpprocrate%</span>几率吸取敌人<span class=\"yellow b\">1</span>点生命上限\n</span></td>\n<td class=\"skilldesc_right b3\">\n</td>\n{template MOD_CLUBBASE_SKILLDESC_MID2}\n<!--{if empty($___TEMP_THIS_SKILL_ACQUIRED)}-->\n<span class=\"yellow b\">\n</span>\n<!--{/if}-->\n{template MOD_CLUBBASE_SKILLDESC_END}\n",
  "/./include/modules/extra/club/skills/skill62/desc": "<!--{eval eval(import_module('skill62'));}-->\n<!--{eval $___TEMP_SKILL_ID=62;}-->\n{template MOD_CLUBBASE_SKILLDESC_START}\n<span>\n腐蚀\n</span>\n{template MOD_CLUBBASE_SKILLDESC_MID1}\n<td class=\"skilldesc_left b3\"><span class=\"skilldesc\">\n<!--{eval $skill62_cnt = (int)\\skillbase\\skill_getvalue(62,'t'); $skill62_used = 7-$skill62_cnt; $skill62_dmgr=$skill62_used*7;}-->\n<span class=\"red b\">限定技&nbsp;本局还可发动<span>$skill62_cnt</span>次</span><br>\n每次发动提升<span class=\"yellow b\">50</span>点生命上限，但你的战斗伤害输出将永久降低<span class=\"yellow b\">7%</span><br>\n<!--{if $skill62_used>0}-->\n<span class=\"cyan b\">你已经发动了这个技能<span>$skill62_used</span>次，你的最终伤害输出将降低$skill62_dmgr%</span><br>\n<!--{/if}-->\n</span></td>\n<td class=\"skilldesc_right b3\">\n<!--{if $skill62_cnt>0}-->\n<input type=\"button\" style=\"width:46px\" onclick=\"$('mode').value='special';$('command').value='skill62_special';$('subcmd').value='upgrade';postCmd('gamecmd','command.php');this.disabled=true;\" value=\"发动\">\n<!--{else}-->\n<input type=\"button\" style=\"width:46px\" disabled=\"true\" value=\"发动\">\n<!--{/if}-->\n</td>\n{template MOD_CLUBBASE_SKILLDESC_MID2}\n<!--{if empty($___TEMP_THIS_SKILL_ACQUIRED)}-->\n<span class=\"yellow b\">\n7级时解锁\n</span>\n<!--{/if}-->\n{template MOD_CLUBBASE_SKILLDESC_END}\n",
