  "/./include/modules/extra/club/skills/skill64/desc": "<!--{eval eval(import_module('skill64'));}-->\n<!--{eval $___TEMP_SKILL_ID=64;}-->\n{template MOD_CLUBBASE_SKILLDESC_START}\n<span>\n索魂\n</span>\n{template MOD_CLUBBASE_SKILLDESC_MID1}\n<td class=\"skilldesc_left b3\"><span class=\"skilldesc\">\n当你击杀敌人时，你的<span class=\"yellow b\">命体上限</span>、<span class=\"yellow b\">经验值</span>、<br><span class=\"yellow b\">全系熟练</span>、<span class=\"yellow b\">基础攻防</span>中随机一项的数值<span class=\"yellow b\">+3～5</span>点<br>\n使用技能“<span class=\"yellow b\">恐惧</span>”击杀敌人时，改为获得上述全部四项的加成\n</span></td>\n<td class=\"skilldesc_right b3\">\n</td>\n{template MOD_CLUBBASE_SKILLDESC_MID2}\n<!--{if empty($___TEMP_THIS_SKILL_ACQUIRED)}-->\n<span class=\"yellow b\">\n15级时解锁\n</span>\n<!--{/if}-->\n{template MOD_CLUBBASE_SKILLDESC_END}\n",
